-- case: {"id": "group_key", "ordered": true}
WITH data AS (
 SELECT 1 AS id, 2 AS k, 'Bee' AS txt, CAST(12.50 AS DECIMAL(10,2)) AS amount, DATE '2024-02-01' AS day
 UNION ALL SELECT 2, 1, 'ant', CAST(3.00 AS DECIMAL(10,2)), DATE '2024-01-02'
 UNION ALL SELECT 3, 2, 'Bee', CAST(12.50 AS DECIMAL(10,2)), DATE '2024-02-01'
 UNION ALL SELECT 4, NULL, NULL, CAST(NULL AS DECIMAL(10,2)), CAST(NULL AS DATE)
 UNION ALL SELECT 5, 1, 'ANT', CAST(-2.25 AS DECIMAL(10,2)), DATE '2024-01-02'
 UNION ALL SELECT 6, 3, '', CAST(0 AS DECIMAL(10,2)), DATE '2024-03-03'
 UNION ALL SELECT 7, 3, 'cat', CAST(7.75 AS DECIMAL(10,2)), DATE '2024-03-03'
 UNION ALL SELECT 8, NULL, NULL, CAST(NULL AS DECIMAL(10,2)), CAST(NULL AS DATE)
)
SELECT k AS k, COUNT(*) AS n FROM data GROUP BY 1 ORDER BY k NULLS FIRST;

